// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class FrontierOmniExternalSorterTest {

	@Test
	void boundedFanInMergesResidentRunsWithoutExtraDiskOverlap(@TempDir Path directory) throws Exception {
		int records = 130;
		long retainedRunBytes = (long) records * FrontierOmniExternalSorter.RECORD_BYTES;
		List<Long> output = new ArrayList<>();
		try (FrontierOmniExternalSorter.Collector collector = FrontierOmniExternalSorter.collector(
				directory, FrontierOmniExternalSorter.RECORD_BYTES, retainedRunBytes)) {
			for (int cell = records - 1; cell >= 0; cell--) {
				collector.add(cell, Long.MIN_VALUE + cell, cell, 7L, 10_000L + cell, 0L);
			}
			collector.finish((cell, priority, subject, predicate, object, context) -> output.add(cell));
		}

		assertEquals(records, output.size());
		for (int cell = 0; cell < records; cell++) {
			assertEquals((long) cell, output.get(cell));
		}
	}

	@Test
	void oneRecordBufferCompletesMultiPassMergeWithinExactPeakEnvelope(@TempDir Path directory) throws Exception {
		int records = 514;
		long retainedRunBytes = (long) records * FrontierOmniExternalSorter.RECORD_BYTES;
		long largestMergeOverlap = 512L * FrontierOmniExternalSorter.RECORD_BYTES;
		List<Long> output = new ArrayList<>();
		try (FrontierOmniExternalSorter.Collector collector = FrontierOmniExternalSorter.collector(
				directory, FrontierOmniExternalSorter.RECORD_BYTES, retainedRunBytes + largestMergeOverlap)) {
			for (int cell = records - 1; cell >= 0; cell--) {
				collector.add(cell, Long.MIN_VALUE + cell, cell, 7L, 10_000L + cell, 0L);
			}
			collector.finish((cell, priority, subject, predicate, object, context) -> output.add(cell));
		}

		assertEquals(records, output.size());
		for (int cell = 0; cell < records; cell++) {
			assertEquals((long) cell, output.get(cell));
		}
		try (var files = Files.list(directory)) {
			assertTrue(files.findAny().isEmpty(), "multi-pass merge must remove its private spill namespace");
		}
	}

	@Test
	void concurrentCollectorsUseIndependentSpillNamespaces(@TempDir Path directory) throws Exception {
		List<String> firstOutput = new ArrayList<>();
		List<String> secondOutput = new ArrayList<>();
		try (FrontierOmniExternalSorter.Collector first = FrontierOmniExternalSorter.collector(
				directory, FrontierOmniExternalSorter.RECORD_BYTES, 1024L * 1024L);
				FrontierOmniExternalSorter.Collector second = FrontierOmniExternalSorter.collector(
						directory, FrontierOmniExternalSorter.RECORD_BYTES, 1024L * 1024L)) {
			first.add(2L, 20L, 2L, 7L, 200L, 0L);
			first.add(1L, 10L, 1L, 7L, 100L, 0L);
			second.add(4L, 40L, 4L, 8L, 400L, 0L);
			second.add(3L, 30L, 3L, 8L, 300L, 0L);

			first.finish((cell, priority, subject, predicate, object, context) -> firstOutput
					.add(cell + ":" + subject));
			second.finish((cell, priority, subject, predicate, object, context) -> secondOutput
					.add(cell + ":" + subject));
		}

		assertEquals(List.of("1:1", "2:2"), firstOutput);
		assertEquals(List.of("3:3", "4:4"), secondOutput);
		try (var files = Files.list(directory)) {
			assertTrue(files.findAny().isEmpty(), "successful collectors must remove every spill artifact");
		}
	}

	@Test
	void concurrentCollectorsShareAndReleaseOneTemporaryDiskReservation(@TempDir Path directory) throws Exception {
		long oneRecord = FrontierOmniExternalSorter.RECORD_BYTES;
		FrontierTemporaryDiskReservation reservation = new FrontierTemporaryDiskReservation(oneRecord);
		FrontierOmniExternalSorter.Collector first = FrontierOmniExternalSorter.collector(
				directory, oneRecord, 1024L, reservation);
		FrontierOmniExternalSorter.Collector second = FrontierOmniExternalSorter.collector(
				directory, oneRecord, 1024L, reservation);
		try {
			first.add(1L, 1L, 1L, 7L, 10L, 0L);
			first.add(2L, 2L, 2L, 7L, 20L, 0L);
			second.add(3L, 3L, 3L, 8L, 30L, 0L);
			assertThrows(FrontierStatisticsException.class,
					() -> second.add(4L, 4L, 4L, 8L, 40L, 0L));
			assertEquals(oneRecord, reservation.reservedBytes());
		} finally {
			first.close();
			second.close();
		}

		assertEquals(0L, reservation.reservedBytes());
		try (var files = Files.list(directory)) {
			assertTrue(files.findAny().isEmpty(), "failed collectors must remove every private spill namespace");
		}
	}
}
